mapper.select:
SELECT
s.id,s.cn_name AS cnName,s.jp_name AS jpName,s.alias,s.first_air_date AS firstAirDate, s.episodes,s.studio,s.country,s.official_site AS officialSite,s.category,s.tags, s.cover_path AS coverPath,s.updated_date AS updatedDate, AVG(c.rating) AS avgRating, COUNT(c.id) AS ratingCount
s.id,s.cn_name AS cnName,s.jp_name AS jpName,s.alias,s.first_air_date AS firstAirDate, s.episodes,s.studio,s.country,s.official_site AS officialSite,s.category,s.tags, s.cover_path AS coverPath,s.updated_date AS updatedDate
FROM subjects s
LEFT JOIN collections c ON c.subject_id = s.id AND c.rating > 0
AND (s.cn_name LIKE CONCAT('%', #{p.keyword}, '%') OR s.jp_name LIKE CONCAT('%', #{p.keyword}, '%') OR s.alias LIKE CONCAT('%', #{p.keyword}, '%'))
AND s.category = #{p.category}
AND s.country = #{p.country}
AND YEAR(s.first_air_date) = #{p.year}
AND MONTH(s.first_air_date) = #{p.month}
AND s.tags LIKE CONCAT('%', #{p.tagKeyword}, '%')
GROUP BY s.id
HAVING 1=1
AND AVG(c.rating) >= #{p.ratingMin}
AND AVG(c.rating) <= #{p.ratingMax}
ORDER BY s.id DESC
